/*
 * The first screen.
 *
 * Two lists, both of them plain lists of text with a hairline between the rows.
 * No card shadows, no rounded blue buttons, no illustration — the words are the
 * interface, and the only thing that separates one row from the next is a line
 * at a tenth of the text colour.
 */

/*
 * **The first screen is wider than the column the page centres.**
 *
 * That column is 660 pixels, which was right when this screen was a list of
 * examples and a status strip. It now also holds the four sentences from the
 * brief and the field you type your own into, and stacking all of that in one
 * narrow column pushes the field — the point of the whole screen — below the
 * fold on the window this interface is designed against.
 *
 * So the launchpad takes its own width and centres itself inside the column it
 * sits in, which is itself centred on the page. The masthead above it and the
 * status strip below it keep the narrow measure, because a heading and a
 * footnote read better short.
 */
.column--launchpad {
  max-width: min(1180px, calc(100vw - 2 * var(--space-6)));
}

.launchpad {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  /* Two rows on the left, each as tall as what is in it, and a third that takes
   * whatever is left — so the left column reads top to bottom with no pool of
   * air in the middle of it while the right column is the tall one. */
  grid-template-rows: auto auto 1fr;
  align-content: start;
  column-gap: var(--space-5);
  row-gap: var(--space-5);
}

/* The two doors, the map that is already drawn and the field you type your own
 * event into stack down the left; the four sentences from the brief take the
 * right. */
.launchpad__doors {
  grid-column: 1;
  grid-row: 1;
}

.launchpad__drawn {
  grid-column: 1;
  grid-row: 2;
}

.launchpad__yours {
  grid-column: 1;
  grid-row: 3;
}

.launchpad__build {
  grid-column: 2;
  grid-row: 1 / -1;
}

/* On a narrow window there is one column and everything stacks, in the order it
 * is written. */
@media (width < 1100px) {
  .launchpad {
    grid-template-columns: minmax(0, 1fr);
  }

  .launchpad__doors,
  .launchpad__drawn,
  .launchpad__yours,
  .launchpad__build {
    grid-column: 1;
    grid-row: auto;
  }
}

/* ---- The two doors ------------------------------------------------------ */

.doors {
  margin: 0;
  padding: 0;
  list-style: none;
  border: 1px solid var(--hairline);
  border-radius: var(--radius);
  background: var(--surface-raised);
}

.door {
  display: grid;
  grid-template-columns: 7rem minmax(0, 1fr);
  gap: var(--space-2);
  align-items: baseline;
  padding: var(--space-1) var(--space-2);
}

.door + .door {
  border-top: 1px solid var(--hairline);
}

.door__name {
  font-size: var(--text-md);
  font-weight: var(--weight-semibold);
  letter-spacing: -0.01em;
  color: var(--text);
}

.door__line {
  font-size: var(--text-sm);
  color: var(--text-muted);
  text-wrap: pretty;
}

/* ---- The examples -------------------------------------------------------- */

.examples {
  margin: 0;
  padding: 0;
  list-style: none;
  border: 1px solid var(--hairline);
  border-radius: var(--radius);
  background: var(--surface-raised);
}

.example {
  display: grid;
  row-gap: var(--space-hair);
  width: 100%;
  margin: 0;
  padding: var(--space-2);
  text-align: left;
  font-family: inherit;
  background: none;
  border: none;
  color: var(--text);
}

/* The one card that opens something. It is a row of text that answers to a
 * click, not a button with a fill: the fill would be the loudest thing on a
 * quiet screen, and what it opens is the point, not the pressing of it. */
.example--live {
  cursor: pointer;
}

.example--live:hover {
  background: var(--surface);
}

.example__claim {
  font-size: var(--text-md);
  font-weight: var(--weight-medium);
  color: var(--text);
  text-wrap: pretty;
}

/* A row that is not a control: nothing is known about it yet, because the
 * server has not answered or because the ask did not come back. It reads
 * quieter than a card that opens something — and the reading, not the quiet, is
 * what says so: it carries no action line and so no arrow after it, which is
 * the mark every row that opens something has and this one cannot. */
.example--waiting .example__claim {
  color: var(--text-muted);
}

.example__line {
  font-size: var(--text-sm);
  color: var(--text-muted);
  text-wrap: pretty;
}

/* The line that says what happens if you take this row up on its offer. */
.example__action {
  display: flex;
  align-items: baseline;
  gap: var(--space-1);
  margin-top: var(--space-hair);
  font-size: var(--text-sm);
  color: var(--accent);
}

.example--live .example__action::after {
  content: "→";
  font-family: var(--font-mono);
}

/* A card that is going to play a recording rather than call a model says so on
 * its own face, in a word with a hairline round it, beside the day it was
 * made. */
.example__badge {
  padding: 0 var(--space-hair);
  border: 1px solid var(--hairline);
  border-radius: 2px;
  font-size: var(--text-sm);
  font-weight: var(--weight-medium);
  color: var(--text);
  white-space: nowrap;
}

/* One hairline between rows, and nothing else separating them. Written last so
 * that it comes after the rules for the rows themselves rather than before,
 * which is the order that makes the cascade easy to follow. */
.examples > li + li {
  border-top: 1px solid var(--hairline);
}

/* The one sentence a copy with no model key says about itself, under the four
 * cards and again under the field. It sits in the ordinary text colour rather
 * than in a warning hue: it is a fact about this copy, not a problem with it. */
.launchpad__keyless {
  margin: var(--space-1) 0 0;
  font-size: var(--text-sm);
  color: var(--text);
  text-wrap: pretty;
}

.example[data-state="replay"] .example__badge {
  color: var(--text-muted);
}

.example--live[data-state] .example__action {
  display: flex;
  align-items: baseline;
  gap: var(--space-1);
}

/* The section that builds a map holds a form as well as a list, so it needs a
 * gap between the two that a bare section does not. Its rows sit at the top of
 * the column rather than stretching to fill it: a list of two doors with a
 * hundred pixels of air inside it reads as a mistake. */
.launchpad > section {
  display: grid;
  align-content: start;
  row-gap: var(--space-2);
}

/* A second sentence under the cards, where there is one: today, the server's own
 * words about a recording it could not read. Quieter than the first, because the
 * first is about what this copy can do and this one is about one file in it. */
.launchpad__keyless--quiet {
  color: var(--text-muted);
}

content.content:
1	/**
2	 * The first screen with no model key.
3	 *
4	 * This is the screen a reviewer with nothing configured meets, so it is the
5	 * screen that has to be honest about what this copy can and cannot do — card by
6	 * card, in one sentence each, with nothing greyed out that would in fact work.
7	 */
8	
9	import { render, screen } from "@testing-library/react";
10	import { describe, expect, it } from "vitest";
11	import type { Readiness } from "../../api/client";
12	import { keylessSentence, Launchpad, STARTING_SENTENCES } from "../Launchpad";
13	
14	/** The one stored example the server ships with. */
15	const EXAMPLES = [
16	  {
17	    id: "hormuz",
18	    title: "Strait of Hormuz",
19	    one_line: "The strait reopens, and what that causes.",
20	  },
21	];
22	
23	/** What the server says when it has no key and all four examples recorded, one day. */
24	const NO_KEY_ALL_FOUR: Readiness = {
25	  status: "not_ready",
26	  model_key_present: false,
27	  replayable: STARTING_SENTENCES.map((one) => ({
28	    example: one.example,
29	    recording_date: "2026-09-18",
30	  })),
31	  unreadable: [],
32	};
33	
34	/** What the server says about itself when it has no key and one recording. */
35	const NO_KEY_ONE_RECORDING: Readiness = {
36	  // Deliberately `not_ready`: this screen reads what can be replayed and whether
37	  // a key is configured, and ignores this field. A program with no key and a
38	  // recording can do everything a reviewer came to see.
39	  status: "not_ready",
40	  model_key_present: false,
41	  replayable: [{ example: "hormuz", recording_date: "2026-09-18" }],
42	  unreadable: [],
43	};
44	
45	/** What it says when it has nothing at all. */
46	const NOTHING: Readiness = {
47	  status: "not_ready",
48	  model_key_present: false,
49	  replayable: [],
50	  unreadable: [],
51	};
52	
53	/**
54	 * What it says when a file in the recordings folder could not be read.
55	 *
56	 * The one that could is still on the list and still plays: a bad file never
57	 * hides the good ones, and it never hides itself either.
58	 */
59	const ONE_BAD_FILE: Readiness = {
60	  status: "not_ready",
61	  model_key_present: false,
62	  replayable: [{ example: "hormuz", recording_date: "2026-09-18" }],
63	  unreadable: [
64	    "gulf-2026-08-02.jsonl could not be read: its header names no example, so there is nothing to offer it against.",
65	  ],
66	};
67	
68	/**
69	 * The section that offers to build a map, on its own.
70	 *
71	 * The screen holds two lists of the same shape — the maps already drawn, and
72	 * the sentences that build one — and counting rows across both couples a claim
73	 * about one to the fixture behind the other.
74	 */
75	function building(container: HTMLElement): HTMLElement {
76	  return container.querySelector(".launchpad__build") as HTMLElement;
77	}
78	
79	/** Draw the first screen. */
80	function draw(readiness: Readiness) {
81	  return render(
82	    <Launchpad
83	      examples={EXAMPLES}
84	      failure={null}
85	      readiness={readiness}
86	      onOpen={() => undefined}
87	      onBuild={() => undefined}
88	    />,
89	  );
90	}
91	
92	describe("with no model key", () => {
93	  it("test_the_keyless_sentence_is_word_for_word", () => {
94	    draw(NO_KEY_ALL_FOUR);
95	
96	    // Record 0012's sentence, word for word, with the day taken from the
97	    // readiness answer — never from a file name, a build date or a clock. It is
98	    // under the four cards, and the field it disables carries it too.
99	    expect(
100	      screen.getByText(
101	        "No model key configured — these four run from recordings made on 2026-09-18.",
102	      ),
103	    ).toBeInTheDocument();
104	    expect(screen.getByLabelText("An event you think will happen")).toBeDisabled();
105	  });
106	
107	  it("test_the_shared_sentence_is_printed_only_when_it_is_true", () => {
108	    // **One recording out of four.** Record 0012's sentence would be a screen
109	    // claiming something a reader can see is false — three cards reading *not
110	    // yet live* under a line saying these four run from recordings.
111	    const { container } = draw(NO_KEY_ONE_RECORDING);
112	    expect(container.textContent).not.toContain("these four run from recordings");
113	    expect(
114	      screen.getByText(
115	        "No model key configured — one of these four runs from recordings, made on " +
116	          "2026-09-18; the midterms, export controls and photonic chips have nothing " +
117	          "recorded yet.",
118	      ),
119	    ).toBeInTheDocument();
120	
121	    // **All four, but not all on one day.** The sentence is never more current
122	    // than the oldest thing it describes, and it says there is more than one day.
123	    const several = draw({
124	      ...NO_KEY_ALL_FOUR,
125	      replayable: STARTING_SENTENCES.map((one, place) => ({
126	        example: one.example,
127	        recording_date: place === 0 ? "2026-09-18" : "2026-09-20",
128	      })),
129	    });
130	    expect(several.container.textContent).toContain(
131	      "No model key configured — these four run from recordings, the oldest made on 2026-09-18.",
132	    );
133	    expect(several.container.textContent).not.toContain(keylessSentence("2026-09-20"));
134	  });
135	
136	  it("test_nothing_is_silently_inert_without_a_key", () => {
137	    const { container } = draw(NO_KEY_ONE_RECORDING);
138	
139	    // The card with a recording runs. It is a button, it is not disabled, and it
140	    // says on its own face that it plays a recording and when it was made.
141	    const recorded = screen.getByRole("button", {
142	      name: new RegExp(STARTING_SENTENCES[0]?.sentence ?? ""),
143	    });
144	    expect(recorded).not.toBeDisabled();
145	    expect(recorded.textContent).toContain("replay");
146	    expect(recorded.textContent).toContain("2026-09-18");
147	
148	    // **The three with nothing recorded get no card at all.** They used to be
149	    // three rows reading *not yet live*, side by side with the one door, taking
